def lstm_parameter_count(input_size, hidden_size):
    # already covered as more parameters than Vanilla RNN in LSTM Architecture: 3 gates plus candidate values
    return 4 * (hidden_size * (input_size + hidden_size) + hidden_size)

def gru_parameter_count(input_size, hidden_size):
    # already covered as two gates instead of three in this topic
    return 3 * (hidden_size * (input_size + hidden_size) + hidden_size)

input_size, hidden_size = 128, 256

lstm_params = lstm_parameter_count(input_size, hidden_size)
gru_params = gru_parameter_count(input_size, hidden_size)

print(f"LSTM parameters: {lstm_params:,}")
print(f"GRU parameters: {gru_params:,}")
print(f"Parameter reduction: {(1 - gru_params / lstm_params) * 100:.1f}% fewer parameters, already covered as the benefit of fewer parameters in this topic")
